# 地堡档案表：dict，键是 id，值是 [姓名, 等级]
archives = {
    1: ["剑圣", 50],
    2: ["奶茶猫", 32],
    3: ["熬夜冠军", 18],
}

# 模拟 UPDATE ... SET level = level + 1 WHERE id = 1
for key in archives:
    if key == 1:
        key += 1          # 想给 id=1 的等级 +1

# 盘点打印
for key in sorted(archives):
    print(key, archives[key][0], archives[key][1])
